                assertEquals(0,window.acknowledgedThrough());f.cleanup(window,cleanup);assertTrue(window.pending().isEmpty());assertEquals(1,window.acknowledgedThrough());assertEquals(2,f.opens);assertArrayEquals(exact,DistributedCommandCodec.encode(f.ackCommands.getLast()));
                var inputPath=root.resolve("reroutes/0/input.bin");byte[] binding=OperatorUpload.sha256(ByteBuffer.allocate(136).put(f.source.schema.digest()).put(f.data.sessionIdentityDigest()).put(f.homes.identityDigest()).putLong(window.grant().epoch()).putLong(window.grant().sessionId().getMostSignificantBits()).putLong(window.grant().sessionId().getLeastSignificantBits()).putLong(window.grant().issuedAtMillis()).putLong(window.grant().expiresAtMillis()).array());try(var input=RatisOperationRerouteJournal.reopen(inputPath,binding)){assertTrue(f.homes.read(input.origin().transactionId()).consumed());}
                assertEquals(CommandResult.Status.SESSION_EXPIRED,CommandResult.decode(f.source.store.operationResult(original.command().operationId(),original.command().receiptDigest())).status());int calls=f.ackCommands.size();f.cleanup(window,cleanup);assertEquals(calls,f.ackCommands.size());
