    @Test void retiredHomeAfterLostProtectedConsumptionSettlesOnlyOriginalForcedProof()throws Exception { consumptionRecovery(true); }
    private void consumptionRecovery(boolean retire)throws Exception {
        try(var f=new Fixture()) {
            var original=f.window.prepareAt(f.source.directory,f.writes(),List.of());assertEquals(CommandResult.Status.SUCCESS,f.execute(f.window,original).status());f.window.acknowledge(original);
            var before=f.catalogue.epochs.read();var advanced=before.advanceTime(SessionEpochLedger.MAX_LIFETIME_MILLIS+11);
            assertEquals(CommandResult.Status.SUCCESS,f.catalogue.epochs.execute(f.catalogue.epochs.prepare(f.outer.operation(3),before,advanced)).status());
            var expired=advanced.issue(new UUID(0,570),2*SessionEpochLedger.MAX_LIFETIME_MILLIS);assertEquals(CommandResult.Status.SUCCESS,f.catalogue.epochs.execute(f.catalogue.epochs.prepare(f.outer.operation(4),advanced,expired)).status());
            var homeRoute=f.homeClient.directory().ranges().getFirst();var bind=f.catalogue.epochs.prepareSessionBinding(f.homeClient.directory(),f.homeGroup,new OperationId(new UUID(0,571),expired.minimumEpoch(),0),expired.grants().getLast(),256,-1);assertEquals(CommandResult.Status.SUCCESS,CommandResult.decode(f.append(homeRoute,DistributedCommandCodec.encode(bind))).status());
            f.loseConsume=true;assertThrows(ExecutionException.class,()->f.cleanup(f.window,f.coordinator));assertEquals(1,f.consumes.size());var exact=f.consumes.getFirst();assertEquals(0,exact.operation().epoch());assertTrue(exact.before().fullyFinalized());assertTrue(exact.next().consumed());assertEquals(2,f.opens);assertTrue(f.window.pending().isEmpty());f.window.close();f.coordinator.close();f.consumeUncertain=false;
            if(retire) {
                var consumed=f.homes.read(exact.before().transactionId());var fences=new ArrayList<ParticipantFenceProof>();
                for(var route:f.source.target.ranges()) {
                    var binding=f.catalogue.epochs.prepareSessionBinding(f.source.target,route.groupId(),new OperationId(new UUID(0,572),expired.minimumEpoch(),0),expired.grants().getLast(),256,-1);assertEquals(CommandResult.Status.SUCCESS,CommandResult.decode(f.append(route,DistributedCommandCodec.encode(binding))).status());
                    var outcome=f.data.finalizedParticipant(route.groupId(),consumed.transactionId());assertNotNull(outcome);f.data.retireParticipant(new ParticipantRetirement(outcome.finalization(),outcome.position(),consumed));
                    assertNull(f.data.finalizedParticipant(route.groupId(),consumed.transactionId()));var identity=new ParticipantIdentity(f.homeGroup,1,route.groupId(),exact.before());var fence=f.data.participantFence(identity);assertNotNull(fence);fences.add(fence);
                }
                var identity=f.homes.identity(consumed,homeRoute);f.homeClient.retireHome(new HomeRetirement(identity,consumed,fences));assertNull(f.homes.read(consumed.transactionId()));assertNotNull(f.homes.fence(identity));
            }
            try(var window=RatisDurableSessionClient.reopen(f.windowPath,f.data);var cleanup=new RatisOperationRerouteCoordinator(root.resolve("reroutes"),f.source.schema,f.catalogue.epochs,f.data,f.homes,f.scheduler,window.grant(),window.limits(),header->{var definition=TopologyChange.Definition.decode(f.point(RatisTopologyCatalogue.definitionKey(header.definitionDigest())));header.requireDefinition(definition);return definition.sourceDirectory();})) {
                f.cleanup(window,cleanup);if(retire){assertNull(f.homes.read(exact.before().transactionId()));try(var journal=RatisDurableTransaction.reopen(root.resolve("reroutes/0/input.bin.atomic"),f.homes,f.data)){var proof=journal.snapshot().homeRetirementProof();assertNotNull(proof);assertEquals(f.homes.identity(exact.before(),homeRoute),proof.identity());}}else assertTrue(f.homes.read(exact.before().transactionId()).consumed());assertEquals(1,f.consumes.size());assertEquals(2,f.opens);assertTrue(window.pending().isEmpty());f.cleanup(window,cleanup);assertEquals(1,f.consumes.size());
            }
        }
    }
